record.field:
action = {
    "type": "ir.actions.act_url",
    "url": ''.join([substr + (str(record.vat[4:]) if record.country_code == 'FR' else str(record.vat[len(record.country_code):]) if record.vat.startswith(record.country_code) else str(record.vat)) for substr in env.context.get('link')]),
    "target": "new",
}

folder = env.ref('documents.document_inbox_folder')
req_docs = env['documents.request_wizard'].create([{
    "folder_id": folder.id,
    "res_id": partner.id,
    "res_model": model._name,
    "name": "Identity Document - " + partner.name,
    "requestee_id": partner.id,
    "partner_id": partner.id,
    "activity_date_deadline_range": 7,
    "activity_note": "Please provide a valid identity document.",
    "x_has_chatter_message": True,
} for partner in records])

if len(req_docs) == 1 and not env.context.get('from_cron'):
    action = {'type': 'ir.actions.act_window', 'res_model': 'documents.request_wizard', 'view_mode': 'form', 'res_id': req_docs.id, 'target': 'new'}
else:
    env.ref('accounting_firm.server_action_request_document_with_chatter_message').with_context(active_model='documents.request_wizard', active_ids=req_docs.ids).run()

for document in records:
    if attachment_id := document.attachment_id.id:
        document.partner_id.message_post(
            body="The Identity Document Scan changed for this one: ",
            attachment_ids=[attachment_id]
        )
action = {
    'type': 'ir.actions.act_window',
    'res_model': 'res.partner',
}
action.update({'view_mode': 'form', 'res_id': records.partner_id.id}) if len(records) == 1 else action.update({'name': 'Contacts', 'view_mode': 'list,form', 'domain': [('id', 'in', records.partner_id.ids)]})
